u6a21\u578b\uff09\u5bf9\u7559\u5b58\u56de\u5408\u505a\u80dc\u8d1f/\u8d28\u91cf\u5224\u5b9a\uff1b\u62bd\u6837\u5b50\u96c6\u7531 \u22652 \u4e2a\u88c1\u5224\u72ec\u7acb\u91cd\u5224\uff0c\u8ba1\u7b97\u4e00\u81f4\u6027\uff08Cohen's \u03ba / \u4e00\u81f4\u7387\uff09\uff1b\u53e6\u5bf9\u540c\u4e00\u88c1\u5224\u4ee5\u4e0d\u540c\u968f\u673a\u79cd\u5b50\u91cd\u5224\u5b50\u96c6\uff0c\u8bc4\u4f30\u518d\u6d4b\u7a33\u5b9a\u6027\uff1b\u4e0d\u4e00\u81f4\u6837\u672c\u7531\u4eba\u5de5\u4ef2\u88c1\u89c4\u5219\u5904\u7406\u5e76\u8bb0\u5f55\u3002\n- **\u62a5\u544a\u683c\u5f0f**\uff1a\u6bcf\u6761\u4ef6\u6bcf\u79cd\u5b50\u7ed9\u51fa \u0394 \u4e0e\u5c40\u5185\u80dc\u7387\uff1b\u4e3b\u8868\u62a5\u544a\u5747\u503c\u3001SD\u3001\u6548\u5e94\u91cf\u300195%CI\uff1b\u4e0d\u5220\u9664\"\u5931\u8d25\"\u79cd\u5b50\uff08\u6536\u655b\u5dee\u4e5f\u7167\u62a5\uff09\uff0c\u53e6\u505a\"\u6536\u655b\u5931\u8d25\u7387\"\u4f5c\u4e3a\u8fc7\u7a0b\u6307\u6807\u3002\n\n## 5. \u63a7\u5236\u4e0e\u7a33\u5065\u6027\n- **\u7b49\u89c4\u6a21\u6f14\u793a\u6570\u636e/\u7b49\u8bad\u7ec3\u8ba1\u7b97**\uff1a\u00a73 \u7684\u8bb0\u8d26\u673a\u5236\u5373\u63a7\u5236\uff1bSFT-only\uff08T1\uff09\u4e0e\u65e0\u8bad\u7ec3\uff08T0\uff09\u5206\u79bb\u8d21\u732e\u3002\n- **2\u00d72**\uff1a\u5728\u5185\u5bb9\u5185\u6bd4\u8f83\u6709\u65e0\u7981\u8bcd\u7ea6\u675f\u4e4b\u5dee\uff0c\u68c0\u9a8c\"\u5bf9\u6297\u6027\"\u800c\u975e\"\u5185\u5bb9\"\u662f\u6548\u5e94\u6765\u6e90\u3002\n- **\u5bf9\u624b\u6c60\u6df7\u5408**\uff1a\u5c40\u5185\u80dc\u7387\u540c\u65f6\u62a5\u5bf9 GPT-4 \u4e0e\u5bf9 round-robin \u5bf9\u624b\uff0c\u907f\u514d\u5355\u4e00\u5bf9\u624b\u504f\u5dee\u3002\n- **\u66ff\u4ee3\u53e3\u5f84**\uff1a\u654f\u611f\u6027\u518d\u5206\u6790\u7528\"\u4ec5\u5916\u90e8\u57fa\u51c6\"\u3001\"\u4ec5\u5c40\u5185\"\u3001\"\u6bcf\u57fa\u51c6\u5355\u72ec \u0394\"\u5206\u522b\u91cd\u8dd1\u4e3b\u6bd4\u8f83\u3002\n\n## 6. \u7edf\u8ba1\u529f\u6548\u4e0e\u6837\u672c\u91cf\uff08\u5047\u5b9a AS9\uff09\n- \u56e0 LLM \u8bad\u7ec3\u6602\u8d35\uff0c\u91c7\u7528\"\u79cd\u5b50\u4e3a\u5355\u4f4d\u7684\u805a\u5408 + \u9898\u9879\u914d\u5bf9\"\u53cc\u5c42\u9762\u589e\u6548\u3002\u63d0\u4f9b\u9884\u5148\u58f0\u660e\u7684\u529f\u6548\u7a0b\u5e8f\uff1a\u7ed9\u5b9a\u9884\u671f\u6548\u5e94\u91cf\uff08\u4ee5\u8bba\u6587\u590d\u73b0\u7684 \u0394 \u4e0e\u79cd\u5b50\u95f4\u65b9\u5dee\u4e3a\u5148\u9a8c\uff09\u3001\u6761\u4ef6\u6570 S\u3001\u9898\u9879\u6570 I\uff0c\u8ba1\u7b97\u53ef\u68c0\u51fa\u6700\u5c0f\u6548\u5e94\u4e0e\u6240\u9700 S\uff1b\u82e5\u65e0\u6cd5\u6ee1\u8db3 S \u9884\u7b97\uff0c\u5219\u4ee5\"\u6548\u5e94\u91cf + 95%CI + \u5b8c\u6574\u62a5\u544a\"\u4e3a\u51c6\u800c\u975e\u663e\u8457\u6027\u5224\u5b9a\uff0c\u5e76\u660e\u793a\u8be5\u6761\u4ef6\u4e0b\u7ed3\u8bba\u7684\u5f3a\u5ea6\u9650\u5236\u3002\n- \u51b3\u7b56\u89c4\u5219\uff1aS \u5efa\u8bae \u2265 6\uff08\u9884\u7b97\u5141\u8bb8\u4e0b \u2265 10\uff09\uff1b\u82e5 S \u4e0d\u8db3 6\uff0c\u4e3b\u6bd4\u8f83\u6807\u6ce8\u4e3a\u63a2\u7d22\u6027\u3002\n\n## 7. \u53ef\u884c\u6027\u8fb9\u754c\uff08\u70b9 4\uff09\n- **\u672c\u8bbe\u8ba1\u578b\u4efb\u52a1\u4e0d\u8fd0\u884c\u4e5f\u4e0d\u58f0\u79f0\u8fd0\u884c\u4efb\u4f55\u5b9e\u9a8c**\uff1b\u672c\u5730\uff08\u65e0 GPU\u3001\u65e0\u7f51\u7edc\u3001\u65e0 torch\uff09\u4ec5\u627f\u8f7d\u8bbe\u8ba1\u6587\u6863\u3001\u6e38\u620f/\u7981\u8bcd\u8868\u6a21\u62df\u5668 smoke-test\u3001\u9898\u96c6\u9884\u5904\u7406\u811a\u672c\u4e0e\u529f\u6548\u8ba1\u7b97 notebook\u2014\u2014\u8fd9\u4e9b\u4e0d\u662f\u5b9e\u9a8c\u7ed3\u8bba\u3002\n- **\u5916\u90e8\u590d\u73b0\u6240\u9700**\uff1aGPU \u96c6\u7fa4\uff08\u5982 8\u00d7A100\uff09\u7528\u4e8e\u4e24\u9636\u6bb5\u8bad\u7ec3\uff1bGPT-4 API \u7528\u4e8e\u6f14\u793a\u6570\u636e\u751f\u6210\u4e0e\u88c1\u5224\uff1b\u5f00\u6e90\u6743\u91cd + \u8bba\u6587\u8d85\u53c2\u6570\uff08\u82e5\u516c\u5f00\uff09\u6216\u672c\u8bbe\u8ba1\u7684\u8d85\u53c2\u914d\u7f6e\uff1b\u6570\u636e\u53ef\u5f97\u6027\u5047\u5b9a\uff08AS \u7ec4\uff09\uff1aGPT-4 \u6f14\u793a\u6570\u636e\u6309\u672c\u8bbe\u8ba1\u81ea\u5efa\u5e76\u5339\u914d\u4e09\u6761\u4ef6\uff0c\u4e0d\u4f9d\u8d56\u8bba\u6587\u672a\u5f00\u653e\u7684\u6570\u636e\uff1b\u82e5\u8bba\u6587\u6570\u636e/\u4ee3\u7801\u516c\u5f00\uff0c\u4f18\u5148\u590d\u73b0\u5176 A \u6761\u4ef6\u4f5c\u951a\u70b9\u518d\u6269\u5c55 B/C\u3002\n\n## 8. \u5047\u5b9a\u6e05\u5355\uff08\u9010\u6761\u6807\u6ce8\"\u5047\u5b9a\"\uff0c\u975e\u5df2\u6838\u5b9e\u4e8b\u5b9e\uff09\u53ca\u5176\u5bf9\u7ed3\u8bba\u6210\u7acb\u8303\u56f4\u7684\u7ea6\u675f\n- **AS1\uff08\u5b66\u751f\u57fa\u5ea7 7B \u7ea7\u5f00\u6e90\u6a21\u578b\uff0c\u5177\u4f53\u578b\u53f7\u5f85\u5b9a\uff09**\uff1a\u7ed3\u8bba\u5bf9\"\u8be5\u6a21\u578b\u4e0e\u8be5\u89c4\u6a21\"\u6210\u7acb\uff1b\u6362\u6a21\u578b\u65cf/\u89c4\u6a21\u9700\u65b0\u589e\u6761\u4ef6\uff0c\u4e0d\u5f97\u5916\u63a8\u3002\n- **AS2\uff08Taboo \u7981\u8bcd\u8868\u6784\u5efa\u65b9\u5f0f\uff0c\u5982\u53d6\u4e0e\u76ee\u6807\u8bcd\u5f3a\u76f8\u5173\u7684 top-N \u8bcd\uff0c\u5177\u4f53\u65b9\u6cd5\u5f85\u5b9a\uff09**\uff1a\u8bcd\u8868\u8d28\u91cf\u76f4\u63a5\u51b3\u5b9a\u6e38\u620f\u96be\u5ea6\u4e0e\u5956\u52b1\uff0c\u4e09\u6761\u4ef6\u9700\u540c\u6cd5\u540c\u96be\u5ea6\u6807\u5b9a\uff1b\u7ed3\u8bba\u9650\u4e8e\u8be5\u8bcd\u8868\u751f\u6210\u6cd5\uff1b\u4e0d\u540c\u8bcd\u8868\u53ef\u80fd\u6539\u53d8\u5bf9\u6297\u5f3a\u5ea6\u4e43\u81f3\u7ed3\u8bba\u3002\n- **AS3\uff08\u81ea\u535a\u5f08 K \u8f6e \u00d7 E \u56de\u5408/\u8f6e\uff09**\uff1a\u89c4\u6a21\u8fc7\u5c0f\u2192\u63d0\u5347\u4e0d\u53ef\u68c0\uff08\u529f\u6548\u95ee\u9898\uff09\uff1b\u89c4\u6a21\u8fc7\u5927\u2192\u5916\u90e8\u53ef\u590d\u73b0\u6027\u53d7\u9650\uff1b\u4e09\u6761\u4ef6\u5fc5\u987b\u4e00\u81f4\u3002\n- **AS4\uff08Giver/Guesser \u5bf9\u79f0\u4ea4\u66ff\u8bad\u7ec3\uff09**\uff1a\u82e5\u771f\u5b9e\u8bba\u6587\u4e3a\u56fa\u5b9a\u5bf9\u624b\u8bad\u7ec3\uff0c\u672c\u8bbe\u8ba1\u7684 A \u6761\u4ef6\u4e0e\u8bba\u6587\u7684\u504f\u5dee\u4f1a\u5f71\u54cd\"\u590d\u73b0\"\u6210\u7acb\u8303\u56f4\u3002\n- **AS5\uff08\u5956\u52b1=\u7a00\u758f\u80dc\u8d1f \u00b1 \u7a20\u5bc6\u5b50\u5956\u52b1\uff0c\u4e09\u6761\u4ef6\u7ed3\u6784\u76f8\u540c\uff09**\uff1a\u82e5\u975e\u5bf9\u6297\u6e38\u620f\u4e2d\u5956\u52b1\u4fe1\u53f7\u8d28\u91cf\u7cfb\u7edf\u6027\u66f4\u5dee\uff0c\"\u5bf9\u6297\u6027\u66f4\u4f18\"\u53ef\u80fd\u4e0e\u5bf9\u6297\u6027\u65e0\u5173\u800c\u662f\u5956\u52b1\u53ef\u5b66\u4e60\u6027\u5dee\u5f02\uff1b\u672c\u8bbe\u8ba1\u7528\u7ed3\u6784\u4e00\u81f4\u7684\u7a00\u758f\u5956\u52b1 + 2\u00d72 \u63a7\u5236\u8be5\u6df7\u6dc6\uff0c\u7ed3\u8bba\u9650\u6b64\u5956\u52b1\u53e3\u5f84\u3002\n- **AS6\uff08GPT-4 \u6f14\u793a\u6570\u636e\u6bcf\u6761\u4ef6\u7b49\u89c4\u6a21\u3001\u53cc\u89d2\u8272\uff09**\uff1a\u6570\u636e\u4e0d\u7b49\u5373\u5f15\u5165\u6df7\u6dc6\uff1b\u89c4\u6a21\u53d7 API \u9884\u7b97\u7ea6\u675f\u3002\n- **AS7\uff08GPT-4 \u4f5c\u88c1\u5224\uff0c\u8f85\u4ee5\u4e00\u81f4\u6027\u68c0\u9a8c\uff09**\uff1a\u88c1\u5224\u6a21\u578b\u504f\u5dee\u5bf9\u4e09\u6761\u4ef6\u540c\u5411\uff0c\u4f46\u4f1a\u626d\u66f2\u7edd\u5bf9\u5e45\u5ea6\uff1b\u4e3b DV \u4e3a\u5916\u90e8\u57fa\u51c6\u6545\u88c1\u5224\u53ea\u5f71\u54cd\u526f DV\u3002\n- **AS8\uff08\"\u63a8\u7406\"\u7684\u64cd\u4f5c\u5316=\u6240\u9009\u57fa\u51c6\u7535\u6c60 + \u5c40\u5185\u80dc\u7387\uff09**\uff1a\u7535\u6c60\u7ec4\u6210\u51b3\u5b9a\"\u63a8\u7406\"\u5185\u6db5\uff1b\u6362\u7535\u6c60\u53ef\u80fd\u5f97\u5230\u4e0d\u540c\u7684\u6bd4\u8f83\u7ed3\u8bba\u3002\n- **AS9\uff08\u79cd\u5b50\u6570\u4e0e\u529f\u6548\u5047\u8bbe\uff09**\uff1aS \u5145\u8db3\u662f\u663e\u8457\u6027\u63a8\u65ad\u7684\u524d\u63d0\uff1b\u4e0d\u8db3\u5219\u4ee5\u6548\u5e94\u91cf+CI \u62a5\u544a\u5e76\u964d\u7ea7\u4e3a\u63a2\u7d22\u6027\u3002\n- **AS10\uff08SPAG \u914d\u65b9\u53ef\u65e0\u91cd\u8c03\u8fc1\u79fb\u5230 20Q/GMC\uff09**\uff1a\u82e5\u914d\u65b9\u5931\u914d\uff0cA \u7684\"\u4f18\u52bf\"\u53ef\u80fd\u6e90\u4e8e\u914d\u65b9\u5bf9\u65b0\u6e38\u620f\u5931\u914d\u800c\u975e\u5bf9\u6297\u6027\uff1b\u4ee5\u540c\u7b49\u7ed3\u6784\u6821\u51c6\u4e0e 2\u00d72 \u63a7\u5236\u6b8b\u4f59\u98ce\u9669\u3002\n\n## 9. \u4ea4\u